export const LOAD_PANEL_ID = 'preserve:load';
export const PHASE_PANEL_PREFIX = 'preserve:phase:';

/** The JS asset this hook is executing from — the build stamp every run logs,
 *  so a stale bundle can never masquerade as the new code again. */
function bundleTag(): string {
  try {
    const url = import.meta.url;
    return url === '' ? 'unknown' : (url.split('/').pop() ?? url);
  } catch {
    return 'unknown';
  }
}

/** The opener ladder: ~60 attempts, 1 s apart — the CLI's post-reset shape. */
export const OPEN_ATTEMPTS = 60;
/** The patient ladder for the phases that reboot the camera: the re-confirm
 *  click is a human act, so the opener waits ten minutes, and Cancel is the
 *  way out of a wait nobody is coming back for. */
export const OPEN_ATTEMPTS_PATIENT = 600;
/** How long the drain's phase listens for the unplug and replug it asks for
 *  — the same ten minutes the patient ladder gives the Connect click. Its
 *  steps are recorded before it starts, so running out only leaves a warning. */
export const REPLUG_WAIT_MS = OPEN_ATTEMPTS_PATIENT * 1000;

export function phasePanelId(phase: PreservePhaseId): string {
  return `${PHASE_PANEL_PREFIX}${phase}`;
}

export function phaseOfPanelId(id: string | null): PreservePhaseId | null {
  if (id?.startsWith(PHASE_PANEL_PREFIX) !== true) return null;
  const name = id.slice(PHASE_PANEL_PREFIX.length);
  return PRESERVE_PHASES.some((meta) => meta.id === name) ? (name as PreservePhaseId) : null;
}

export interface RunFileSave {
  readonly runId: string;
  /** The last completed step the file carries, or 'created' for a fresh one. */
  readonly afterStep: PreserveStepId | 'created' | 'loaded' | 'manual';
  readonly at: string;
  readonly bytes: number;
  /** The name it downloaded under (or was loaded from). */
  readonly fileName: string;
}

/**
 * The delivered 4 MiB image held against the backup taken before the first
 * write: every block the backup read must come back identical in it, and the
 * blocks only the whole-part dump reaches (the backup holds 0xFF there) are
 * counted apart when they hold data.
 */
export interface DeliveredCheck {
  readonly blocksCompared: number;
  /** Flash addresses of the backed-up blocks the delivered image differs in. */
  readonly differing: readonly number[];
  /** Flash addresses of the blocks only the whole-part dump could read that
   *  are not erased — what the full dump adds over a stock read. */
  readonly onlyInFullDump: readonly number[];
}

const BLOCK = 0x10000;

function isErased(bytes: Uint8Array): boolean {
  return bytes.every((byte) => byte === 0xff);
}

export function checkDelivered(delivered: Uint8Array, backup: Uint8Array): DeliveredCheck | null {
  if (delivered.length !== backup.length || delivered.length % BLOCK !== 0) return null;
  const backedUp = new Set(preservationWindows().map((entry) => entry.address));
  const differing: number[] = [];
  const onlyInFullDump: number[] = [];
  for (let at = 0; at < delivered.length; at += BLOCK) {
    const address = FLASH_BASE + at;
    const mine = delivered.subarray(at, at + BLOCK);
    if (backedUp.has(address)) {
      const theirs = backup.subarray(at, at + BLOCK);
      if (mine.some((byte, index) => byte !== theirs[index])) differing.push(address);
    } else if (!isErased(mine)) {
      onlyInFullDump.push(address);
    }
  }
  return { blocksCompared: backedUp.size, differing, onlyInFullDump };
}

export interface PreservePanelParams {
  readonly runner: Runner;
  readonly device: DeviceHandle;
  readonly form: OptionsForm;
}

export interface PreservePhaseRunOptions {
  /** The explicit past-commit jump, armed through the danger dialog. */
  readonly allowJump?: boolean;
  /**
   * The power-cycle assertion core's backup retry gate waits for: the row's
   * "I power-cycled the camera" control arms it after a failed backup, and
   * the press itself is the assertion — core cannot observe a power cycle.
   */
  readonly powerCycled?: boolean;
}

/**
 * What the wizard is waiting for the USER to do — the expected hand-offs of a
 * run, which the page shows as a calm "your turn" ask rather than as a
 * warning:
 *  - `reconnect`: the camera restarted and Chrome no longer knows it (no USB
 *    serial number), so the step waits for the "Connect device" pick;
 *  - `replug`: the drain on a patch without the arm tail's cursor reset ends
 *    by waiting for an unplug, a replug and the Connect pick;
 *  - `replug-before-restore`: that wait ended unseen — the replug is still
 *    owed before the restore;
 *  - `power-cycle`: a step refused on a spent reader — replug, Connect, and
 *    run the same step again.
 * The first two clear themselves; the last two stand until the next phase
 * starts.
 */
export interface PreservePrompt {
  readonly phase: PreservePhaseId;
  readonly kind: 'reconnect' | 'replug' | 'replug-before-restore' | 'power-cycle';
}

export interface PreservePanelApi {
  readonly loadReporter: ReporterHandle;
  readonly phaseReporters: Readonly<Record<PreservePhaseId, ReporterHandle>>;
  /** The live run state — set when phase ① creates the run, or on resume. */
  readonly state: PreserveRunState | null;
  readonly hasCheckpoint: (name: CheckpointName) => boolean;
  readonly activePhase: PreservePhaseId | null;
  /** The hand-off the wizard is waiting on, or null. */
  readonly prompt: PreservePrompt | null;
  readonly loading: boolean;
  readonly lastSave: RunFileSave | null;
  /** The delivered image against the backup, once both are in hand. */
  readonly deliveredCheck: DeliveredCheck | null;
  /**
   * True once any panel's camera session on this page sent the unlock token: the camera then stays unlocked until it
   * is swapped or power-cycled. The flag is the device's, shared by every panel. The wizard's own reset keeps it, and
   * a camera that leaves outside the reset window clears it (TESTING.md 42.57, 42.59). Nothing is gated on it.
   */
  readonly unlockNote: boolean;
  runPhase: (phase: PreservePhaseId, options?: PreservePhaseRunOptions) => Promise<void>;
  /**
   * Choose the banks step 03 writes (core's `choosePreserveBanks`): after step 02 has read them,
   * until the commit has run or been tried. Returns null when the choice took, or why it did not.
   * The choice rides in the run state, so the next run file records it.
   */
  chooseBanks: (choice: PreserveBankChoice) => string | null;
  cancel: () => void;
  saveAgain: () => void;
  loadRunFile: (file: File) => Promise<void>;
}

function lastCompletedStep(state: PreserveRunState): PreserveStepId | 'created' {
  let last: PreserveStepId | 'created' = 'created';
  for (const meta of PRESERVE_PHASES) {
    for (const id of meta.steps) {
      if (state.steps[id]?.status === 'done') last = id;
    }
  }
  return last;
}

function waitMs(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve) => {
    const tick = setTimeout(resolve, ms);
    signal.addEventListener(
      'abort',
      () => {
        clearTimeout(tick);
        resolve();
      },
      { once: true },
    );
  });
}

/** How many authorized Seek cameras `getDevices()` answers with, or null when
 *  Chrome cannot be asked. vid/pid is all the identity this camera offers, so
 *  with two of them on the bus, which one came back cannot be told apart. */
async function authorizedCameraCount(): Promise<number | null> {
  const usb = getWebUsb();
  if (usb === null) return null;
  try {
    const known = await usb.getDevices();
    return known.filter((candidate) => candidate.vendorId === SEEK_VENDOR_ID).length;
  } catch {
    return null;
  }
}

export function usePreservePanel(params: PreservePanelParams): PreservePanelApi {
  const { runner, device, form } = params;

  const loadReporter = useReporter(t('preserve:status.noFile'));
  /* Three fixed hook calls, one per phase — each phase's bar, status and log
   * live in its own RunPanel for the whole life of the wizard. */
  const phaseReporters: Readonly<Record<PreservePhaseId, ReporterHandle>> = {
    'read-build': useReporter(t('preserve:status.notRun')),
    'patch-dump': useReporter(t('preserve:status.notRun')),
    'restore-verify': useReporter(t('preserve:status.notRun')),
  };
  const reportersRef = useRef(phaseReporters);
  reportersRef.current = phaseReporters;

  const [state, setState] = useState<PreserveRunState | null>(null);
  const [lastSave, setLastSave] = useState<RunFileSave | null>(null);
  const [prompt, setPrompt] = useState<PreservePrompt | null>(null);
  /* The camera's unlock flag is the device's, shared with every panel (TESTING.md 42.59). A phase's sessions mark it at
   * each close, below. */
  const unlockNote = device.unlocked;
  /* Clears only the reconnect ask: the camera came back, by the user's pick or
   * by Chrome's own re-grant. */
  const clearReconnect = useCallback((): void => {
    setPrompt((current) => (current?.kind === 'reconnect' ? null : current));
  }, []);

  const stateRef = useRef<PreserveRunState | null>(null);
  const checkpoints = useRef<Map<CheckpointName, Uint8Array>>(new Map());
  const extra = useRef<Map<string, Uint8Array>>(new Map());

  const applyState = useCallback((next: PreserveRunState): void => {
    stateRef.current = next;
    setState(next);
  }, []);

  const hasCheckpoint = useCallback((name: CheckpointName): boolean => {
    return checkpoints.current.has(name);
  }, []);

  /* ---- the run file ---------------------------------------------------- */

  /* `label` names what the run had got to in the file name — the last
   * completed step, or the step that failed or was cancelled. */
  const saveRunFile = useCallback((after: RunFileSave['afterStep'], label?: string): void => {
    const current = stateRef.current;
    if (current === null) return;
    const now = new Date();
    const zip = buildRunFile(current, checkpoints.current, extra.current, now);
    const fileName = runFileName(
      current.runId,
      now,
      label ??
        (after === 'created' || after === 'loaded' || after === 'manual'
          ? after
          : STEP_FILE_LABEL[after]),
    );
    downloadBytes(zip, fileName, 'application/zip');
    setLastSave({
      runId: current.runId,
      afterStep: after,
      at: now.toISOString(),
      bytes: zip.length,
      fileName,
    });
  }, []);

  /* ---- the session opener ladder --------------------------------------- */

  /* The ladder outlives the render that built it — a phase holds its opener
   * across the reset — so it reads the device seat through this ref. The
   * `device` handle the phase started with is a snapshot: its `.device` is
   * the USBDevice that dropped, never null, so a ladder reading it would
   * never re-adopt and never tell the user to re-connect. */
  const deviceRef = useRef(device);
  deviceRef.current = device;

  const makeOpener = useCallback(
    (
      phase: PreservePhaseId,
      rep: ReporterHandle,
      signal: AbortSignal,
      patient = false,
    ): { opener: SessionOpener; closeAll: () => Promise<void> } => {
      const opened: WebUsbTransport[] = [];
      /* The sessions this opener made, so a close can say whether any of them
       * sent the unlock token before its transport goes. */
      const sessions: SeekDevice[] = [];
      const closeAll = async (): Promise<void> => {
        /* Each session that sent the token marks the camera's flag, on the connection it was opened on (TESTING.md 42.59). */
        for (const session of sessions) {
          if (session.unlockTokenAccepted) deviceRef.current.markUnlocked(session.transport);
        }
        sessions.splice(0);
        for (const transport of opened.splice(0)) {
          try {
            await transport.close();
          } catch {
            /* the device is gone; the close is best-effort */
          }
        }
      };
      const opener: SessionOpener = {
        open: async () => {
          const options = readOptions(form);
          let lastError: unknown = null;
          /* A camera that reboots loses Chrome's permission — this unit has no
           * USB serial number, so Chrome cannot re-recognise it — and only the
           * user's "Connect device" click re-grants it. The opener therefore
           * waits PATIENTLY (the phase that resets asks for the long ladder;
           * Cancel is the escape hatch) and tells the user exactly what to
           * click, once, at the moment it matters. */
          const attempts = patient ? OPEN_ATTEMPTS_PATIENT : OPEN_ATTEMPTS;
          let instructed = false;
          for (let attempt = 0; attempt < attempts; attempt++) {
            if (signal.aborted) throw new CancelledError('cancelled while opening the camera');
            try {
              /* makeTransport reads the LIVE device, so an attempt that
               * lands after the reset's re-enumeration opens the camera
               * that came back, not the object that dropped. */
              const transport = deviceRef.current.makeTransport({
                recipient: options.recipient,
                onWarning: (message) => {
                  rep.log(message, 'warn');
                },
              });
              opened.push(transport);
              const client = new SeekDevice(transport, { reporter: rep.reporter, signal });
              sessions.push(client);
              await transport.open();
              if (instructed) clearReconnect();
              return client;
            } catch (error) {
              lastError = error;
              if (attempt === 0) {
                /* On the phases that restart the camera this is the restart
                 * itself — expected, so the log says so plainly and keeps the
                 * wire's own words as detail. */
                rep.log(
                  patient
                    ? `the camera is restarting — waiting for it to come back ` +
                        `(${errorMessage(error)})`
                    : `camera did not open (${errorMessage(error)}) — retrying for up to ` +
                        `${String(Math.round(attempts / 60))} min; a camera that has just been ` +
                        'reset is silent for a couple of seconds while it boots',
                  patient ? 'detail' : 'warn',
                );
                rep.setStatus(t('preserve:status.restarting'));
              }
              /* A missed `connect` event must not strand the run: the camera
               * re-enumerates while the page holds nothing, and getDevices()
               * finds it when Chrome still holds the grant. When the grant is
               * GONE (this camera has no serial number, so every reboot is a
               * new device to Chrome), the re-confirm is the user's click —
               * say so, loudly, once. */
              if (deviceRef.current.device === null) {
                const reattached = await deviceRef.current.reattach();
                if (reattached) {
                  if (instructed) clearReconnect();
                  rep.log('the camera is back on the bus — re-adopted it', 'ok');
                } else if (!instructed && attempt >= 2) {
                  /* Not a fault: Chrome keeps no grant for a camera without a
                   * USB serial number, so every restart ends in this pick. */
                  instructed = true;
                  setPrompt({ phase, kind: 'reconnect' });
                  rep.log(
                    'Your turn: press "Connect device" and pick the camera. It restarted as ' +
                      'planned, and Chrome cannot recognise it again by itself (it has no USB ' +
                      'serial number). The step carries on as soon as you pick it.',
                    'info',
                  );
                  rep.setStatus(t('preserve:status.waitConnect'));
                } else if (instructed && attempt % 30 === 29) {
                  rep.log(
                    `still waiting — press "Connect device" and pick the camera ` +
                      `(${String(attempt + 1)} s)`,
                    'detail',
                  );
                }
              }
            }
            await waitMs(1000, signal);
          }
          /* English: the run file records it as the step's error; stepErrorText shows it translated. */
          throw new Error(cameraNotBackEnglish(Math.round(attempts / 60), errorMessage(lastError)));
        },
        close: closeAll,
      };
      return { opener, closeAll };
    },
    [clearReconnect, form],
  );

  /* ---- the generation guard: the reset is not a swap -------------------- */

  const generation = useRef(device.generation);
  /* Set when the current phase saw its camera leave, so the reconnect that
   * follows can be recognised as the reset's re-enumeration. */
  const sawDisconnect = useRef(false);
  /* Set while the drain's phase waits for the unplug and replug. The guard
   * records the departure as the unplug (a poll could miss a quick one) and
   * leaves the arrival to the wait, which runs the count check itself and
   * ends the phase on its verdict. */
  const replugWatch = useRef<{ unplugged: boolean } | null>(null);

  const stopForSwap = useCallback(
    (rep: ReporterHandle, why: string): void => {
      runner.cancel();
      sawDisconnect.current = false;
      rep.log(`${why} — stopping the phase (the camera may be a different unit)`, 'warn');
      rep.setStatus(t('preserve:status.swapped'));
    },
    [runner],
  );

  useEffect(() => {
    if (generation.current === device.generation) return;
    generation.current = device.generation;
    const phase = phaseOfPanelId(runner.active);
    if (phase === null) {
      sawDisconnect.current = false;
      return;
    }
    const rep = reportersRef.current[phase];

    if (device.device === null) {
      if (replugWatch.current !== null) {
        replugWatch.current.unplugged = true;
        sawDisconnect.current = true;
        rep.reporter.log(
          'the camera is unplugged — plug it back in, then press "Connect device" and pick it',
          'detail',
        );
        rep.setStatus(t('preserve:status.waitPlugBack'));
        return;
      }
      /* A device LEFT. On a phase that resets the camera this is the reset
       * itself — the opener ladder is already riding through the boot
       * silence, and the reconnect below re-adopts the unit. Anywhere else
       * it is an unplugged camera: stop. */
      if (RESETS_CAMERA.has(phase)) {
        sawDisconnect.current = true;
        rep.reporter.log(
          'the camera is restarting, as expected — waiting for it to come back',
          'detail',
        );
        rep.setStatus(t('preserve:status.restarting'));
        return;
      }
      stopForSwap(rep, 'the camera left the bus mid-phase');
      return;
    }

    /* A device ARRIVED. It is only the reset's re-enumeration when this
     * phase saw the drop first; a camera appearing with the seat still
     * filled (or refilled out of nowhere) is a second unit on the bus. */
    if (!RESETS_CAMERA.has(phase) || !sawDisconnect.current) {
      stopForSwap(rep, 'a camera appeared on the bus mid-phase');
      return;
    }
    sawDisconnect.current = false;
    if (replugWatch.current !== null) return;
    /* THE COUNT CHECK: vid/pid is all the identity this camera offers, so
     * with more than one authorized camera on the bus, WHICH one came back
     * cannot be told apart — stop, and let the steps' own version/bank
     * gates be the backstop against anything that slipped through. (An
     * advisory check: when Chrome cannot be asked, the gates decide.) */
    void (async () => {
      const units = await authorizedCameraCount();
      if (units !== null && units > 1) {
        stopForSwap(
          rep,
          `${String(units)} authorized cameras answered when the camera ` +
            're-enumerated — the one that came back cannot be told apart',
        );
        return;
      }
      clearReconnect();
      rep.reporter.log('the camera is back — continuing', 'ok');
      rep.setStatus(t('preserve:status.back'));
    })();
  }, [clearReconnect, device, runner, stopForSwap]);

  /* ---- the replug that ends the drain's phase ---------------------------- */

  /**
   * The drain exhausts the camera's reader, and the wire reboot does not
   * revive it — only a power cycle does (TESTING.md secs. 28.4, 35). So the
   * phase that drains ends by asking for one, and WATCHES for it: the camera
   * must leave the bus (the unplug), then a camera must fill the seat again
   * (the replug, and the Connect click Chrome needs for a camera with no
   * serial). The phase's steps are recorded and the run file saved before
   * this starts, so a wait that is cancelled or runs out only leaves a
   * warning behind.
   */
  const awaitReplug = useCallback(
    async (
      phase: PreservePhaseId,
      rep: ReporterHandle,
      signal: AbortSignal,
    ): Promise<'replugged' | 'ambiguous' | 'not-seen'> => {
      const before = deviceRef.current.device;
      const watch = { unplugged: before === null };
      replugWatch.current = watch;
      setPrompt({ phase, kind: 'replug' });
      rep.log(
        'Your turn: unplug the camera, plug it back in, then press "Connect device" and pick ' +
          'it. This run’s patch predates the reader fix, so the camera needs a fresh power-up ' +
          'before the restore. The run file is already saved.',
        'info',
      );
      rep.setStatus(t('preserve:status.waitReplug'));
      try {
        const deadline = Date.now() + REPLUG_WAIT_MS;
        while (Date.now() < deadline && !signal.aborted) {
          const seat = deviceRef.current.device;
          if (seat === null) {
            watch.unplugged = true;
          } else if (watch.unplugged && seat !== before) {
            const units = await authorizedCameraCount();
            if (units !== null && units > 1) {
              rep.log(
                `${String(units)} authorized cameras answered when the camera came back — ` +
                  'which one is plugged in cannot be told apart; leave only the camera this run ' +
                  'patched connected before the restore (its version and bank checks are the ' +
                  'backstop)',
                'warn',
              );
              return 'ambiguous';
            }
            rep.log('the camera is back on a fresh boot — the restore can run', 'ok');
            return 'replugged';
          }
          await waitMs(250, signal);
        }
        return 'not-seen';
      } finally {
        replugWatch.current = null;
        setPrompt((current) => (current?.kind === 'replug' ? null : current));
      }
    },
    [],
  );

  /* ---- run one phase ---------------------------------------------------- */

  /* One runner task per phase, so the camera lock is held for the whole
   * phase: through the reset, the boot silence, the re-pick and the replug
   * wait, which all happen inside it. */
  const runPhase = useCallback(
    async (phase: PreservePhaseId, options: PreservePhaseRunOptions = {}): Promise<void> => {
      const outcome = await runner.start(phasePanelId(phase), async (signal) => {
        const rep = phaseReporters[phase];
        const meta = phaseMeta(phase);
        sawDisconnect.current = false;
        setPrompt(null);
        rep.reset(
          meta.resetsCamera ? t('preserve:status.runningRestarts') : t('preserve:status.running'),
        );
        const allowJump = options.allowJump === true;

        let current = stateRef.current;
        if (current === null) {
          if (phase !== 'read-build') {
            rep.log('no run is active — the first phase creates the run', 'error');
            rep.setStatus(t('preserve:status.noRun'));
            return;
          }
          try {
            /* The chunk the form holds is the drain's ask size, as the
             * CLI's global --chunk is. Core's default (64) is the ask
             * measured exact on silicon. */
            const opts = readOptions(form);
            const created = await createPreserveRun({ drainChunk: opts.chunk });
            current = created.state;
            applyState(current);
            rep.reporter.log(`run ${current.runId} created`, 'detail');
            /* THE BUILD STAMP: which JS asset this run is executing from. A
             * stale tab has masqueraded as the new code three times — Chrome
             * caches the page hard — so every run names its bundle. It is a
             * file name, so it goes to the run file, not the log (42.105). */
            extra.current.set(
              `${PHASE_FOLDER['read-build']}/${PAGE_BUILD_FILE}`,
              new TextEncoder().encode(`${bundleTag()}\n`),
            );
          } catch (error) {
            rep.log(`cannot create the run: ${errorMessage(error)}`, 'error');
            logHint(rep.log, error);
            rep.setStatus(t('preserve:status.notCreated'));
            return;
          }
        }

        /* English: this gate's reason goes to the run log. */
        const gate = canRunPhase({
          state: current,
          phase,
          has: hasCheckpoint,
          translate: tEnglish,
        });
        /* The power-cycle assertion the row's re-run control armed satisfies
         * the gate's one power-cycle gap — core's own retry gate takes the
         * same flag, so the panel must not refuse what core will accept. */
        const powerCycleArmed = gate.needsPowerCycle && options.powerCycled === true;
        if (!gate.ok && !(gate.jumpable && allowJump) && !powerCycleArmed) {
          rep.log(`refused: this phase ${gateReason(gate, tEnglish) ?? 'cannot run'}`, 'error');
          rep.setStatus(t('preserve:status.refused'));
          return;
        }
        if (allowJump && gate.jumpable) {
          rep.reporter.log(
            'Jumping past the unrecorded write, on your word that the writes landed ' +
              'without their checkpoints — the steps’ own version and bank checks still run',
            'warn',
          );
        }

        const load = artifactLoader(checkpoints.current, extra.current);
        const { opener, closeAll } = makeOpener(phase, rep, signal, meta.resetsCamera);
        let stepInFlight: PreserveStepId | null = null;
        const ran = new Set<PreserveStepId>();
        /* The reset window (TESTING.md 42.59): on a phase that resets the camera, the camera leaving the bus while its
         * steps run is the wizard's own reset, and the unlock flag is kept. The window closes when the steps are done,
         * so the replug the drain asks for afterwards is a power cycle and clears the flag. */
        if (meta.resetsCamera) deviceRef.current.setResetWindow(true);
        try {
          for (const step of meta.steps) {
            if (current.steps[step]?.status === 'done') {
              rep.reporter.log(`${stepMeta(step).label} — already done, skipping`, 'detail');
              continue;
            }
            if (allowJump && step === 'commit' && current.steps.commit?.status === 'failed') {
              rep.reporter.log(
                'Jumping past the write: it is not written again — an attempt is on record and ' +
                  'the bank was read as already patched; going on with the whole-flash read',
                'warn',
              );
              continue;
            }
            stepInFlight = step;
            const outcome = await runPreserveStep(
              step,
              opener,
              current,
              load,
              rep.reporter,
              signal,
              {
                ...(allowJump ? { allowJump: true } : {}),
                ...(options.powerCycled === true ? { powerCycled: true } : {}),
              },
            );
            stepInFlight = null;
            for (const artifact of outcome.artifacts) {
              if (isCheckpointName(artifact.name)) {
                checkpoints.current.set(artifact.name, artifact.data);
              } else if (artifact.name !== RUN_STATE_FILE) {
                /* Filed under the step that made it — the run file's folders. */
                extra.current.set(`${PHASE_FOLDER[phase]}/${artifact.name}`, artifact.data);
              }
            }
            current = outcome.state;
            applyState(current);
            ran.add(step);
            rep.reporter.log(`${stepMeta(step).label} — done`, 'ok');
          }
          saveRunFile(lastCompletedStep(current));
          deviceRef.current.setResetWindow(false);
          const lastStep = meta.steps.at(-1);
          const replugOwed =
            meta.replugAfter &&
            lastStep !== undefined &&
            ran.has(lastStep) &&
            !drainLeavesReaderReadable(current);
          if (meta.replugAfter && lastStep !== undefined && ran.has(lastStep) && !replugOwed) {
            /* The patched image's arm tail resets the whole cursor — by the
             * fifth site on the 2014 trio builds, by its own tail on 1.0.3.0:
             * the drain left the reader readable, and the restore reads on
             * this boot (TESTING.md secs. 36, 38). */
            rep.reporter.log(
              'The patched firmware leaves the camera readable after the whole-flash read, so ' +
                'no replug is needed; the restore runs on this start.',
              'detail',
            );
          }
          if (replugOwed) {
            const replug = await awaitReplug(phase, rep, signal);
            if (replug !== 'replugged') {
              if (replug === 'not-seen') {
                setPrompt({ phase, kind: 'replug-before-restore' });
                rep.log(
                  (signal.aborted
                    ? 'the replug wait was stopped'
                    : `no replug seen in ${String(Math.round(REPLUG_WAIT_MS / 60_000))} min`) +
                    ' — before the restore, unplug the camera, plug it back in and press ' +
                    '"Connect device"',
                  'info',
                );
              }
              rep.reporter.progress(1, 1, t('preserve:status.doneReplug', { phase: meta.label }));
              return;
            }
          }
          rep.reporter.progress(1, 1, t('preserve:status.done', { phase: meta.label }));
        } catch (error) {
          if (!isCancelledStep(error)) {
            /* The drain's planned stop is logged as a stop, not an error (TESTING.md 42.102). */
            if (unpatchedStartOf(error) !== null) {
              rep.log(`Stopped: ${errorMessage(error)}`, 'warn');
            } else {
              rep.log(`ERROR: ${errorMessage(error)}`, 'error');
            }
            logHint(rep.log, error);
            if (isPowerCycleRefusal(error)) setPrompt({ phase, kind: 'power-cycle' });
            /* The drain's planned stop (the start entered a bank the run did not patch) is
             * not a failure: core's words say what happened and that the restore comes next. */
            /* A backup that refuses the camera wrote nothing, and its words say what to do. */
            rep.setStatus(
              unpatchedStartOf(error) !== null
                ? coreText(PRESERVE_UNPATCHED_START_STOP_MESSAGE)
                : stepInFlight === 'backup' &&
                    error instanceof SeekError &&
                    error.code === 'pipeline/refused'
                  ? t('preserve:status.backupRefused')
                  : t('preserve:status.failed'),
            );
            /* A failed STEP is a fact about the run: record it so a resume
             * sees it, and refresh the file. A CANCELLED step is not
             * recorded — the previous checkpoint stands (core's rule). The
             * steps that DID finish inside this phase keep their records
             * either way, so the file names them. */
            const failedStep = stepInFlight;
            if (failedStep !== null) {
              current = recordStepFailure(current, failedStep, error);
              applyState(current);
            }
            saveRunFile(
              lastCompletedStep(current),
              failedStep === null ? undefined : `${STEP_FILE_LABEL[failedStep]}-failed`,
            );
          } else {
            rep.log('cancelled', 'warn');
            rep.setStatus(t('preserve:status.cancelled'));
            /* The steps that finished before the cancel are recorded in
             * memory; put them in the file too, so closing the tab here
             * does not take a recorded commit with it. */
            saveRunFile(
              lastCompletedStep(current),
              stepInFlight === null ? undefined : `${STEP_FILE_LABEL[stepInFlight]}-cancelled`,
            );
          }
        } finally {
          deviceRef.current.setResetWindow(false);
          await closeAll();
          rep.flush();
        }
      });
      if (outcome === 'in-use-elsewhere') reportInUseElsewhere(phaseReporters[phase]);
    },
    [applyState, awaitReplug, form, hasCheckpoint, makeOpener, phaseReporters, runner, saveRunFile],
  );

  /* ---- resume from a run file ------------------------------------------ */

  /* Reads a file, never the camera: no camera lock. */
  const loadRunFile = useCallback(
    async (file: File): Promise<void> => {
      await runner.start(
        LOAD_PANEL_ID,
        async () => {
          const rep = loadReporter;
          rep.reset(t('preserve:status.readingFile'));
          try {
            const bytes = new Uint8Array(await file.arrayBuffer());
            rep.reporter.log(`${file.name} — ${String(bytes.length)} B`, 'detail');
            const parsed = parseRunFile(bytes);
            checkpoints.current = new Map(parsed.checkpoints);
            extra.current = new Map(parsed.extra);
            applyState(parsed.state);
            for (const meta of PRESERVE_PHASES) {
              const phaseRep = phaseReporters[meta.id];
              const records = meta.steps.map((id) => parsed.state.steps[id]);
              if (records.every((record) => record?.status === 'done')) {
                phaseRep.reset(t('preserve:status.doneEarlier'));
              } else if (records.some((record) => record?.status === 'failed')) {
                const failed = records.find((record) => record?.status === 'failed');
                phaseRep.reset(
                  t('preserve:status.failedEarlier', {
                    error:
                      (failed?.error === undefined
                        ? undefined
                        : stepErrorText(failed.errorCode, failed.error)) ??
                      t('preserve:unknownReason'),
                  }),
                );
              } else {
                phaseRep.reset(t('preserve:status.notRun'));
              }
            }
            rep.reporter.log(
              'run ' +
                parsed.state.runId +
                ' — created ' +
                parsed.state.createdAt +
                ', schema version ' +
                String(parsed.state.version),
              'detail',
            );
            if (parsed.state.expectedVersion !== undefined) {
              rep.reporter.log(`firmware ${parsed.state.expectedVersion}`, 'detail');
            }
            rep.reporter.log(
              'the firmware images derive from the camera’s own banks — the run file carries ' +
                'them; nothing else is needed',
              'detail',
            );
            rep.reporter.log(
              parsed.state.targets === undefined
                ? `banks to write: not chosen yet (the choice: ${bankChoiceWords(parsed.state.choice)})`
                : `banks to write: ${bankListWords(parsed.state.targets)} ` +
                    `(the choice: ${bankChoiceWords(parsed.state.choice)})`,
              'detail',
            );
            rep.reporter.log(
              `checkpoints loaded: ${[...parsed.checkpoints.keys()].join(', ') || 'none yet'}`,
              'detail',
            );
            rep.reporter.progress(
              1,
              1,
              t('preserve:status.resumed', { step: parsed.state.nextStep }),
            );
            setLastSave({
              runId: parsed.state.runId,
              afterStep: 'loaded',
              at: new Date().toISOString(),
              bytes: bytes.length,
              fileName: file.name,
            });
          } catch (error) {
            rep.log(`cannot resume from this file: ${errorMessage(error)}`, 'error');
            logHint(rep.log, error);
            rep.setStatus(t('preserve:status.notResumed'));
          } finally {
            rep.flush();
          }
        },
        { camera: false },
      );
    },
    [applyState, loadReporter, phaseReporters, runner],
  );

  const chooseBanks = useCallback(
    (choice: PreserveBankChoice): string | null => {
      const current = stateRef.current;
      if (current === null) return t('preserve:banks.refusedNoRun');
      if (runner.busy) return t('preserve:banks.refusedBusy');
      try {
        applyState(choosePreserveBanks(current, choice));
        return null;
      } catch (error) {
        return coreText(errorCoreMessage(error) ?? errorMessage(error));
      }
    },
    [applyState, runner.busy],
  );

  const cancel = useCallback((): void => {
    runner.cancel();
    const phase = phaseOfPanelId(runner.active);
    if (phase !== null) phaseReporters[phase].setStatus(t('shared:status.cancelling'));
  }, [phaseReporters, runner]);

  const saveAgain = useCallback((): void => {
    const current = stateRef.current;
    if (current === null) return;
    saveRunFile(lastCompletedStep(current));
  }, [saveRunFile]);

  /* Recomputed whenever the run state moves: the checkpoints it reads are
   * filed before the state that names them is applied. */
  const deliveredCheck = useMemo((): DeliveredCheck | null => {
    if (state?.deliveredSha256 === undefined) return null;
    const delivered = checkpoints.current.get(PRESERVE_DUMP_ORIGINAL_FILE);
    const backup = checkpoints.current.get(PRESERVE_BACKUP_FILE);
    if (delivered === undefined || backup === undefined) return null;
    return checkDelivered(delivered, backup);
  }, [state]);

  return useMemo(
    () => ({
      loadReporter,
      phaseReporters,
      state,
      hasCheckpoint,
      activePhase: phaseOfPanelId(runner.active),
      prompt,
      loading: runner.active === LOAD_PANEL_ID,
      lastSave,
      deliveredCheck,
      unlockNote,
      runPhase,
      chooseBanks,
      cancel,
      saveAgain,
      loadRunFile,
    }),
    [
      loadReporter,
      phaseReporters,
      state,
      hasCheckpoint,
      runner.active,
      prompt,
      lastSave,
      deliveredCheck,
      unlockNote,
      runPhase,
      chooseBanks,
      cancel,
      saveAgain,
      loadRunFile,
    ],
  );
}
