/**
 * Error taxonomy. Callers branch on `code`, never on message text — messages are
 * for humans and are expected to change.
 */
import { recordedParam, type CoreMessage } from './message.js';

export type SeekErrorCode =
  /** A caller passed an option outside its accepted range. */
  | 'options/invalid'
  | 'usb/transfer-failed'
  | 'usb/timeout'
  | 'usb/stalled'
  | 'usb/not-open'
  | 'device/error-code'
  | 'device/mode'
  | 'device/window'
  /**
   * The camera did not report its firmware version, so nothing that could mean
   * something else on another build was sent. See `SAFE_BEFORE_IDENTITY`.
   */
  | 'device/version-unknown'
  | 'image/malformed'
  | 'image/unsupported'
  | 'image/key-table'
  | 'flash/refused'
  | 'flash/commit'
  | 'family/unsupported'
  /**
   * The v1 full-flash preservation pipeline refused to proceed — a gate that
   * exists to keep a write from landing somewhere other than the slot the
   * camera boots (a bank capture that is not the factory image, a boot-config
   * word that names no slot, a build the patch was not derived from). The
   * image guards in `image/bank.ts` report `flash/refused`; this code marks the
   * preservation pipeline's own gates. See `src/preservation/`.
   */
  | 'pipeline/refused'
  /** The slot workflows (`src/slots/`) refused: an unsupported build, slot or input. Nothing was sent. */
  | 'slots/refused'
  | 'cancelled';

export interface SeekErrorOptions extends ErrorOptions {
  /** Device-reported status word, when one is available. */
  readonly deviceCode?: number;
  /** Extra structured context for logs and reports. */
  readonly detail?: Readonly<Record<string, unknown>>;
  /** The message as a code + params, for the page (`message` stays the English). */
  readonly coreMessage?: CoreMessage;
}

export class SeekError extends Error {
  readonly code: SeekErrorCode;
  readonly deviceCode: number | undefined;
  readonly detail: Readonly<Record<string, unknown>> | undefined;
  /** The message as a code + params, where the thrower gave one. */
  readonly coreMessage: CoreMessage | undefined;

  constructor(code: SeekErrorCode, message: string, options: SeekErrorOptions = {}) {
    super(message, options);
    this.name = 'SeekError';
    this.code = code;
    this.deviceCode = options.deviceCode;
    this.detail = options.detail;
    this.coreMessage = options.coreMessage;
  }
}

/** An error's message as a code + params, when it is a SeekError that carries one. */
export function errorCoreMessage(error: unknown): CoreMessage | undefined {
  return error instanceof SeekError ? error.coreMessage : undefined;
}

/**
 * An error as a message param: its message while it still says the error's English, else the English.
 * A plain Error (a USB failure, a bug) is its English.
 */
export function errorParam(error: unknown): CoreMessage | string {
  return recordedParam(errorCoreMessage(error), errorMessage(error));
}

/** Raised when the caller's AbortSignal fires. Never indicates a device fault. */
export class CancelledError extends SeekError {
  constructor(message = 'cancelled') {
    super('cancelled', message);
    this.name = 'CancelledError';
  }
}

export function isSeekError(value: unknown): value is SeekError {
  return value instanceof SeekError;
}

/** Message extraction that never throws, for logging unknown catch values. */
export function errorMessage(value: unknown): string {
  if (value instanceof Error) return value.message;
  return String(value);
}
